                + " enemies=" + state.aliveEnemies
                + " score=" + state.player.score
        );
    }

    private void initWindow() {
        if (GraphicsEnvironment.isHeadless()) {
            throw new IllegalStateException("Graphical mode requires a desktop environment");
        }

        panel = new GamePanel(renderer);
        panel.setPreferredSize(new Dimension(GameConstants.WINDOW_WIDTH, GameConstants.WINDOW_HEIGHT));
        panel.setMinimumSize(new Dimension(900, 650));
        panel.setBackground(Color.BLACK);
        panel.setFocusable(true);
        panel.addKeyListener(input);

        window = new JFrame("COBOL-DOOM Java");
        window.setDefaultCloseOperation(JFrame.DO_NOTHING_ON_CLOSE);
        window.addWindowListener(new WindowAdapter() {
            @Override
            public void windowClosing(WindowEvent e) {
                state.running = false;
                shutdown();
            }
        });
        window.setContentPane(panel);
        window.pack();
        window.setLocationRelativeTo(null);
        window.setVisible(true);
        panel.requestFocusInWindow();
        logic.beginFrame(System.currentTimeMillis());
        panel.repaint();
    }

    private void onFrame() {
        if (!state.running) {
            shutdown();
            return;
        }

        logic.beginFrame(System.currentTimeMillis());
        input.beginFrame();
        logic.update(input);
        if (panel != null) {
            panel.repaint();
        }
    }

