import java.awt.event.KeyEvent;

final class GameLogic {
    private final GameState state;

    GameLogic(GameState state) {
        this.state = state;
    }

    void beginFrame(long now) {
        state.currentTime = now;
        if (state.lastFrameTime == 0L) {
            state.deltaTime = 0;
        } else {
            state.deltaTime = (int) (now - state.lastFrameTime);
        }
        state.lastFrameTime = now;
    }

    void update(InputState input) {
        switch (state.mode) {
            case TITLE:
                updateTitle(input);
                break;
            case PLAYING:
                handleInput(input);
                updateEnemies();
                checkPickups();
                tickEffects();
                break;
            case DEAD:
                if (input.justPressed(KeyEvent.VK_R)) {
                    state.mode = GameMode.TITLE;
                }
                if (input.justPressed(KeyEvent.VK_X) || input.justPressed(KeyEvent.VK_ESCAPE)) {
                    state.running = false;
                }
                break;
            case WON:
                if (input.justPressed(KeyEvent.VK_R)) {
                    state.mode = GameMode.TITLE;
                }
                if (input.justPressed(KeyEvent.VK_X) || input.justPressed(KeyEvent.VK_ESCAPE)) {
                    state.running = false;
                }
                break;
            case INTERMISSION:
                if (input.hasAnyJustPressed()) {
                    state.currentLevel++;
                    if (state.currentLevel > 3) {
                        state.mode = GameMode.WON;
                    } else {
                        setupLevel();
                        state.mode = GameMode.PLAYING;
                    }
                }
                break;
            default:
                break;
        }

        state.frameCount++;
    }

