/* ── Terminal I/O ─────────────────────────────────────────────── */

static struct termios orig_termios;
static int raw_mode_enabled = 0;
static unsigned int frame_num = 0;

void enable_raw_mode(void) {
    if (raw_mode_enabled) return;
    tcgetattr(STDIN_FILENO, &orig_termios);
    struct termios raw = orig_termios;
    raw.c_lflag &= ~(ECHO | ICANON | ISIG);
    raw.c_cc[VMIN] = 0;
    raw.c_cc[VTIME] = 0;
    tcsetattr(STDIN_FILENO, TCSAFLUSH, &raw);
    printf("\033[?1049h\033[?25l");
    fflush(stdout);
    raw_mode_enabled = 1;
}

void disable_raw_mode(void) {
    if (!raw_mode_enabled) return;
    tcsetattr(STDIN_FILENO, TCSAFLUSH, &orig_termios);
    printf("\033[?25h\033[0m\033[?1049l");
    fflush(stdout);
    raw_mode_enabled = 0;
}

int read_key(void) {
    unsigned char c = 0;
    if (read(STDIN_FILENO, &c, 1) == 1) {
        if (c == 27) {
            unsigned char seq[2];
            if (read(STDIN_FILENO, &seq[0], 1) != 1) return 27;
            if (read(STDIN_FILENO, &seq[1], 1) != 1) return 27;
            if (seq[0] == '[') {
                switch (seq[1]) {
                    case 'A': return 200;
                    case 'B': return 201;
                    case 'C': return 202;
                    case 'D': return 203;
                }
            }
            return 27;
        }
        return (int)c;
    }
    return 0;
}

long long get_time_ms(void) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    return (long long)tv.tv_sec * 1000LL + tv.tv_usec / 1000LL;
}

void flush_output(void) { fflush(stdout); }
void frame_sleep(void) { usleep(16000); }

int compute_sin(int a) { return (int)(sin((double)a/100.0*M_PI/180.0)*10000.0); }
int compute_cos(int a) { return (int)(cos((double)a/100.0*M_PI/180.0)*10000.0); }

/* ── Line-of-sight check ────────────────────────────────────── */

int check_los_c(int x1, int y1, int x2, int y2,
                const char *map, int mw, int mh) {
    double fx1 = x1/100.0, fy1 = y1/100.0;
    double fx2 = x2/100.0, fy2 = y2/100.0;
    double dx = fx2-fx1, dy = fy2-fy1;
    double dist = sqrt(dx*dx + dy*dy);
    if (dist < 0.01) return 1;
    int steps = (int)(dist * 5);
    if (steps < 1) steps = 1;
    if (steps > 120) steps = 120;
    for (int i = 1; i < steps; i++) {
        double t = (double)i / (double)steps;
        int mx = (int)(fx1 + dx * t);
        int my = (int)(fy1 + dy * t);
        if (mx < 0 || mx >= mw || my < 0 || my >= mh) return 0;
        char c = map[my * mw + mx];
        if (c != '.') return 0;
    }
    return 1;
}

