final class InputState extends KeyAdapter {
    private final boolean[] pressed = new boolean[1024];
    private final boolean[] previous = new boolean[1024];
    private final boolean[] justPressed = new boolean[1024];
    private boolean anyJustPressed = false;

    @Override
    public void keyPressed(KeyEvent e) {
        int code = e.getKeyCode();
        if (code >= 0 && code < pressed.length) {
            pressed[code] = true;
        }
    }

    @Override
    public void keyReleased(KeyEvent e) {
        int code = e.getKeyCode();
        if (code >= 0 && code < pressed.length) {
            pressed[code] = false;
        }
    }

    void beginFrame() {
        anyJustPressed = false;
        for (int i = 0; i < pressed.length; i++) {
            justPressed[i] = pressed[i] && !previous[i];
            previous[i] = pressed[i];
            if (justPressed[i]) {
                anyJustPressed = true;
            }
        }
    }

    boolean isPressed(int keyCode) {
        return keyCode >= 0 && keyCode < pressed.length && pressed[keyCode];
    }

    boolean justPressed(int keyCode) {
        return keyCode >= 0 && keyCode < justPressed.length && justPressed[keyCode];
    }

    boolean hasAnyJustPressed() {
        return anyJustPressed;
    }

    void setSingleFrameKey(int keyCode) {
        Arrays.fill(pressed, false);
        if (keyCode >= 0 && keyCode < pressed.length) {
            pressed[keyCode] = true;
        }
    }
